pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Owned c;

    function setUp() public {
        c = new Owned();
    }

    function _run(address _newOwner) internal {
        vm.assume(_newOwner != address(0));
        bool success;
        try c.setOwner(_newOwner) returns (bool __r) { success = __r; } catch { return; }
        address newOwner;
        try c.owner() returns (address __r) { newOwner = __r; } catch { return; }
        assertTrue(success && newOwner == _newOwner);
    }

    function testFuzz_run(address _newOwner) public {
